    const scheduleHostedMoneySessionRenewal = (view, targetPane, frame, sessionStartedAt = Date.now()) => {
      if (!HOSTED_MONEY_SETTINGS_VIEWS[view] || !targetPane || !frame) return;
      const portalCleanup = frame.__moneyPortalFrameCleanup;
      let renewalDeadline = Number(sessionStartedAt) + MONEY_PORTAL_SESSION_RENEW_MS;
      let renewalTimer = null;
      let renewing = false;
      let lastDeadlineExtensionAt = 0;
      const cleanups = [];
      const renewNow = () => {
        if (renewing || !frame.isConnected || paneMoney?.dataset?.moneyActiveView !== view) return;
        renewing = true;
        console.info(`[Money iframe:settings-tab:${view}] renewing session in place`, {
          timestamp:new Date().toISOString(),
          sessionStartedAt:new Date(sessionStartedAt).toISOString(),
          renewalDeadline:new Date(renewalDeadline).toISOString(),
          promptBoundaryMs:MONEY_PORTAL_IDLE_PROMPT_MS,
          renewalIntervalMs:MONEY_PORTAL_SESSION_RENEW_MS
        });
        // The provider cookie is shared by every frame on its origin. Remove
        // the current frame before logout/authentication so an offscreen frame
        // cannot invalidate a still-visible portal session.
        void renderHostedMoneySettings(view, { force:true });
      };
      const checkDeadline = () => {
        if (!frame.isConnected || paneMoney?.dataset?.moneyActiveView !== view) return;
        const remaining = renewalDeadline - Date.now();
        if (remaining <= 0) {
          renewNow();
          return;
        }
        if (renewalTimer) window.clearTimeout(renewalTimer);
        renewalTimer = window.setTimeout(checkDeadline, remaining);
      };
      const extendDeadline = (source) => {
        if (renewing || !frame.isConnected || paneMoney?.dataset?.moneyActiveView !== view) return;
        const now = Date.now();
        // A single focus transition can be visible through both the iframe
        // focus event and the parent-window blur fallback. Count it once.
        if (now - lastDeadlineExtensionAt < 250) return;
        lastDeadlineExtensionAt = now;
        renewalDeadline = now + MONEY_PORTAL_SESSION_RENEW_MS;
        console.info(`[Money iframe:settings-tab:${view}] session renewal extended`, {
          timestamp:new Date(now).toISOString(),
          source,
          renewalDeadline:new Date(renewalDeadline).toISOString(),
          intervalMs:MONEY_PORTAL_SESSION_RENEW_MS
        });
        checkDeadline();
      };
      const onFrameFocus = () => extendDeadline('iframe-focus');
      const onParentBlur = () => window.setTimeout(() => {
        if (document.activeElement === frame) extendDeadline('iframe-focus-fallback');
      }, 0);
      const onParentFocus = () => {
        if (document.activeElement === frame) extendDeadline('iframe-window-focus');
        else checkDeadline();
      };
      const onVisibilityChange = () => {
        // Forward's idle timer also treats document visibility changes as
        // activity, so mirror that reset in our earlier renewal deadline.
        extendDeadline(`visibility-${document.visibilityState}`);
      };
      frame.addEventListener('focus', onFrameFocus, true);
      cleanups.push(() => frame.removeEventListener('focus', onFrameFocus, true));
      window.addEventListener('blur', onParentBlur, true);
      cleanups.push(() => window.removeEventListener('blur', onParentBlur, true));
      window.addEventListener('focus', onParentFocus, true);
      cleanups.push(() => window.removeEventListener('focus', onParentFocus, true));
      window.addEventListener('pageshow', checkDeadline, true);
      cleanups.push(() => window.removeEventListener('pageshow', checkDeadline, true));
      document.addEventListener('visibilitychange', onVisibilityChange, true);
      cleanups.push(() => document.removeEventListener('visibilitychange', onVisibilityChange, true));
      checkDeadline();
      frame.__moneyPortalFrameCleanup = () => {
        if (renewalTimer) window.clearTimeout(renewalTimer);
        cleanups.splice(0).forEach((cleanup) => cleanup());
        portalCleanup?.();
      };
    };
