              <button class="cs-btn ghost" type="button" data-cap-preset-load="${String(escapeHtml(preset.id))}">${(globalThis.PlatformLanguage?.htmlText("settings","m_90c1cbad9013ee","Load into editor") ?? "Load into editor")}</button>
