                <button class="cs-btn ghost" type="button" data-cap-preset-delete="${escapeHtml(preset.id)}" style="color:#b42318">${(globalThis.PlatformLanguage?.htmlText("settings","m_4fc60207629a44","Delete") ?? "Delete")}</button>
