        showToast((globalThis.PlatformLanguage?.text("settings","m_da588d88602e4f","Preset loaded") ?? "Preset loaded"), ((v0) => globalThis.PlatformLanguage?.text("settings","m_53b8fc72f43b20",`"${v0}" is loaded as unsaved changes. Review and save to apply.`,{v0}) ?? `"${v0}" is loaded as unsaved changes. Review and save to apply.`)(preset.name), true);
