        if (window.FirstMateReportPreview) { draw(); return; }
        if (!window.__fmReportPreviewLoading) window.__fmReportPreviewLoading = new Promise((resolve, reject) => { const script = document.createElement('script'); script.src = '/libraries/apps/settings/report-preview.js?v=20261020-original-roof-layout-v7'; script.onload = resolve; script.onerror = reject; document.head.append(script); });
